    local item = label(self.Sidebar, name, UDim2.new(), UDim2.new(1, -18, 0, 18), 9, Theme.TextDim, Enum.Font.GothamBold)
    item.Name = name .. "Group"
    item.LayoutOrder = order
    padding(item, 9)
    self.groupLabels[name] = item
end

