local BINDABLE = {"Speed", "Jump", "Noclip", "Fly"}

function Movement.new(ctx)
    local self = setmetatable({
        ctx = ctx,
        Speed = false, SpeedValue = 24,
        Jump = false, JumpValue = 80,
        Noclip = false,
        Fly = false, FlySpeed = 55,
        Bindings = {Speed = nil, Jump = nil, Noclip = nil, Fly = nil},
        BindModes = {Speed = "Toggle", Jump = "Toggle", Noclip = "Toggle", Fly = "Toggle"},
        BindHeld = {}, BindControls = {}, ModeControls = {},
        OriginalCollision = {}, HumanoidConnections = {},
    }, Movement)

    local page = ctx.Window:AddPage("Movement", "Движение и телепорт к игроку")
    local stack = ctx.Window:ModuleStack(page, 70)
    local speed = stack:Add("Speed", 172)
    self.SpeedControl = ctx.Window:Toggle(speed.Settings, UDim2.fromOffset(10, 4), 190, "Enabled", false, function(v)
        self:SetFeature("Speed", v, true, false)
    end)
    self.SpeedValueControl = ctx.Window:Slider(speed.Settings, 48, "Strength", 24, 0, 200, 1, function(v) self.SpeedValue = v; self:ApplyHumanoid(); ctx.Touch() end)
    self:BuildBinding(speed.Settings, 88, "Speed")

    local jump = stack:Add("Jump", 172)
    self.JumpControl = ctx.Window:Toggle(jump.Settings, UDim2.fromOffset(10, 4), 190, "Enabled", false, function(v)
        self:SetFeature("Jump", v, true, false)
    end)
    self.JumpValueControl = ctx.Window:Slider(jump.Settings, 48, "Strength", 80, 25, 250, 1, function(v) self.JumpValue = v; self:ApplyHumanoid(); ctx.Touch() end)
    self:BuildBinding(jump.Settings, 88, "Jump")

    local noclip = stack:Add("NoClip", 132)
    self.NoclipControl = ctx.Window:Toggle(noclip.Settings, UDim2.fromOffset(10, 4), 190, "Enabled", false, function(v)
        self:SetFeature("Noclip", v, true, false)
    end)
    self:BuildBinding(noclip.Settings, 48, "Noclip")

    local fly = stack:Add("Fly", 172)
    self.FlyControl = ctx.Window:Toggle(fly.Settings, UDim2.fromOffset(10, 4), 190, "Enabled", false, function(v)
        self:SetFeature("Fly", v, true, false)
    end)
    self.FlyValueControl = ctx.Window:Slider(fly.Settings, 48, "Strength", 55, 10, 250, 1, function(v) self.FlySpeed = v; ctx.Touch() end)
    self:BuildBinding(fly.Settings, 88, "Fly")

    local teleport = stack:Add("Teleport", 310)
    self:BuildTeleport(teleport.Settings)

    ctx.Janitor:Add(ctx.Players.PlayerAdded:Connect(function() self:RenderPlayers() end))
    ctx.Janitor:Add(ctx.Players.PlayerRemoving:Connect(function() task.defer(function() self:RenderPlayers() end) end))
    ctx.Janitor:Add(ctx.LocalPlayer.CharacterAdded:Connect(function()
        self:StopFly(); table.clear(self.OriginalCollision)
        self:DisconnectHumanoid()
        task.defer(function() self:WatchHumanoid(); self:ApplyHumanoid() end)
    end))
    ctx.Janitor:Add(ctx.UserInputService.InputBegan:Connect(function(input)
        self:HandleBindBegan(input)
    end))
    ctx.Janitor:Add(ctx.UserInputService.InputEnded:Connect(function(input)
        self:HandleBindEnded(input)
    end))
    ctx.Janitor:Add(function() self:DisconnectLoops() end)
    self:WatchHumanoid()
    return self
end

function Movement:BuildBinding(parent, y, feature)
    local mode = self.ctx.Window:Button(parent, UDim2.fromOffset(10, y), UDim2.new(0.5, -15, 0, 34), "Mode: Toggle", function()
        if self.BindHeld[feature] then
            self.BindHeld[feature] = false
            self:SetFeature(feature, false, false, true)
        end
        self.BindModes[feature] = self.BindModes[feature] == "Hold" and "Toggle" or "Hold"
        self:DrawBinding(feature)
        self.ctx.Touch()
    end)
    local bind = self.ctx.Window:Button(parent, UDim2.new(0.5, 5, 0, y), UDim2.new(0.5, -15, 0, 34), "Bind: None", function()
        if self.CapturingBind and self.CapturingBind ~= feature then self:DrawBinding(self.CapturingBind) end
        self.CapturingBind = feature
        self:DrawBinding(feature)
    end)
    self.ModeControls[feature], self.BindControls[feature] = mode, bind
    self:DrawBinding(feature)
end

function Movement:DrawBinding(feature)
    local mode = self.ModeControls[feature]
    local bind = self.BindControls[feature]
    if mode then mode.Text = "Mode: " .. (self.BindModes[feature] or "Toggle") end
    if bind then
        bind.Text = self.CapturingBind == feature and "ESC / Del / key..." or "Bind: " .. (self.Bindings[feature] or "None")
    end
end

function Movement:SetFeature(feature, value, touchConfig, updateControl)
    value = value == true
    self[feature] = value
    if feature == "Speed" then
        if value then self:ApplyHumanoid() else self:RestoreSpeed() end
    elseif feature == "Jump" then
        if value then self:ApplyHumanoid() else self:RestoreJump() end
    elseif feature == "Noclip" then
        if not value then self:RestoreCollision() end
    elseif feature == "Fly" and not value then
        self:StopFly()
    end
    if updateControl then
        local control = self[feature .. "Control"]
        if control then control.Set(value) end
    end
    self:RefreshLoops()
    if touchConfig then self.ctx.Touch() end
end

function Movement:HandleBindBegan(input)
    if self.CapturingBind then
        local feature = self.CapturingBind
        if input.KeyCode == Enum.KeyCode.Escape then
            self.CapturingBind = nil
        elseif input.KeyCode == Enum.KeyCode.Delete or input.KeyCode == Enum.KeyCode.Backspace then
            self.Bindings[feature] = nil
            if self.BindHeld[feature] then self:SetFeature(feature, false, false, true) end
            self.BindHeld[feature] = false
            self.CapturingBind = nil
            self.ctx.Touch()
        else
            local name = inputName(input)
            if name then
                self.Bindings[feature] = name
                self.CapturingBind = nil
                self.ctx.Touch()
            end
        end
        self:DrawBinding(feature)
        return
    end
    -- Game actions (for example Forsaken sprint on LeftShift) set
    -- gameProcessedEvent. Custom binds must still receive the same key.
    if isTyping(self.ctx) then return end
    local name = inputName(input)
    if not name then return end
    for _, feature in ipairs(BINDABLE) do
        if self.Bindings[feature] == name then
            if self.BindModes[feature] == "Hold" then
                self.BindHeld[feature] = true
                self:SetFeature(feature, true, false, true)
            else
                self:SetFeature(feature, not self[feature], true, true)
            end
        end
    end
end

function Movement:HandleBindEnded(input)
    local name = inputName(input)
    if not name then return end
    for _, feature in ipairs(BINDABLE) do
        if self.BindModes[feature] == "Hold" and self.BindHeld[feature] and self.Bindings[feature] == name then
            self.BindHeld[feature] = false
            self:SetFeature(feature, false, false, true)
        end
    end
end

function Movement:DisconnectLoops()
    if self.NoclipLoop then self.NoclipLoop:Disconnect(); self.NoclipLoop = nil end
    if self.MovementLoop then self.MovementLoop:Disconnect(); self.MovementLoop = nil end
end

function Movement:RefreshLoops()
    if self.Noclip and not self.NoclipLoop then
        self.NoclipLoop = self.ctx.RunService.Stepped:Connect(function() self:StepNoclip() end)
    elseif not self.Noclip and self.NoclipLoop then
        self.NoclipLoop:Disconnect(); self.NoclipLoop = nil
    end

    local active = self.Speed or self.Jump or self.Fly
    if active and not self.MovementLoop then
        self.MovementLoop = self.ctx.RunService.Heartbeat:Connect(function()
            local ok, message = pcall(function() self:StepMovement() end)
            if not ok and not self.Warned then self.Warned = true; warn("[BezNigativa/Movement] " .. tostring(message)) end
        end)
    elseif not active and self.MovementLoop then
        self.MovementLoop:Disconnect(); self.MovementLoop = nil
    end
end

function Movement:CharacterParts()
    local character = self.ctx.LocalPlayer.Character
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    local root = character and character:FindFirstChild("HumanoidRootPart")
    return character, humanoid, root
end

function Movement:DisconnectHumanoid()
    for _, connection in ipairs(self.HumanoidConnections) do pcall(function() connection:Disconnect() end) end
    table.clear(self.HumanoidConnections)
    self.ActiveHumanoid = nil
end

function Movement:WatchHumanoid()
    local _, humanoid = self:CharacterParts()
    if not humanoid or self.ActiveHumanoid == humanoid then return humanoid end
    self:DisconnectHumanoid()
    self.ActiveHumanoid = humanoid
    self.DefaultWalkSpeed = humanoid.WalkSpeed
    self.DefaultJumpPower = humanoid.JumpPower
    self.DefaultJumpHeight = humanoid.JumpHeight
    local function enforce()
        if (self.Speed or self.Jump) and not self.ApplyingMovement then self:ApplyHumanoid() end
    end
    for _, property in ipairs({"WalkSpeed", "JumpPower", "JumpHeight", "UseJumpPower"}) do
        local connection = humanoid:GetPropertyChangedSignal(property):Connect(enforce)
        table.insert(self.HumanoidConnections, connection)
        self.ctx.Janitor:Add(connection)
    end
    return humanoid
end

function Movement:ApplyHumanoid()
    local humanoid = self:WatchHumanoid()
    if not humanoid or self.ApplyingMovement then return end
    self.ApplyingMovement = true
    local ok, message = pcall(function()
        if self.Speed and humanoid.WalkSpeed ~= self.SpeedValue then humanoid.WalkSpeed = self.SpeedValue end
        if self.Jump then
            if humanoid.UseJumpPower then
                if humanoid.JumpPower ~= self.JumpValue then humanoid.JumpPower = self.JumpValue end
            elseif humanoid.JumpHeight ~= math.max(7.2, self.JumpValue / 7) then
                humanoid.JumpHeight = math.max(7.2, self.JumpValue / 7)
            end
        end
    end)
    self.ApplyingMovement = false
    if not ok then error(message) end
end

function Movement:RestoreSpeed()
    local _, humanoid = self:CharacterParts()
    if not humanoid then return end
    humanoid.WalkSpeed = self.DefaultWalkSpeed or 16
end

function Movement:RestoreJump()
    local _, humanoid = self:CharacterParts()
    if not humanoid then return end
    if humanoid.UseJumpPower then humanoid.JumpPower = self.DefaultJumpPower or 50
    else humanoid.JumpHeight = self.DefaultJumpHeight or 7.2 end
end

function Movement:StepNoclip()
    if not self.Noclip then return end
    local character = self.ctx.LocalPlayer.Character
    if not character then return end
    for _, part in ipairs(character:GetDescendants()) do
        if part:IsA("BasePart") then
            if self.OriginalCollision[part] == nil then self.OriginalCollision[part] = part.CanCollide end
            part.CanCollide = false
        end
    end
end

function Movement:RestoreCollision()
    for part, value in pairs(self.OriginalCollision) do
        if part.Parent then part.CanCollide = value end
    end
    table.clear(self.OriginalCollision)
end

function Movement:FlyObjects(root)
    if self.FlyRoot ~= root or not self.FlyVelocity or not self.FlyGyro then
        self:StopFly()
        local velocity = Instance.new("BodyVelocity")
        velocity.Name = "BezNigativaFlyVelocity"
        velocity.MaxForce = Vector3.new(1, 1, 1) * math.huge
        velocity.Velocity = Vector3.new(0, 0, 0)
        velocity.Parent = root
        local gyro = Instance.new("BodyGyro")
        gyro.Name = "BezNigativaFlyGyro"
        gyro.MaxTorque = Vector3.new(1, 1, 1) * math.huge
        gyro.P = 90000
        gyro.CFrame = root.CFrame
        gyro.Parent = root
        self.FlyRoot, self.FlyVelocity, self.FlyGyro = root, velocity, gyro
    end
end

function Movement:StopFly()
    if self.FlyVelocity then self.FlyVelocity:Destroy() end
    if self.FlyGyro then self.FlyGyro:Destroy() end
    self.FlyRoot, self.FlyVelocity, self.FlyGyro = nil, nil, nil
end

function Movement:StepMovement()
    if self.Speed or self.Jump then self:ApplyHumanoid() end
    local _, humanoid, root = self:CharacterParts()
    if not self.Fly then return end
    local camera = workspace.CurrentCamera
    if not humanoid or not root or not camera then return end
    self:FlyObjects(root)
    humanoid.PlatformStand = false
    local input = self.ctx.UserInputService
    local direction = Vector3.new(0, 0, 0)
    if input:IsKeyDown(Enum.KeyCode.W) then direction += camera.CFrame.LookVector end
    if input:IsKeyDown(Enum.KeyCode.S) then direction -= camera.CFrame.LookVector end
    if input:IsKeyDown(Enum.KeyCode.D) then direction += camera.CFrame.RightVector end
    if input:IsKeyDown(Enum.KeyCode.A) then direction -= camera.CFrame.RightVector end
    if input:IsKeyDown(Enum.KeyCode.Space) then direction += Vector3.new(0, 1, 0) end
    if input:IsKeyDown(Enum.KeyCode.LeftControl) then direction -= Vector3.new(0, 1, 0) end
    self.FlyVelocity.Velocity = direction.Magnitude > 0 and direction.Unit * self.FlySpeed or Vector3.new(0, 0, 0)
    self.FlyGyro.CFrame = CFrame.lookAt(root.Position, root.Position + camera.CFrame.LookVector)
end

function Movement:BuildTeleport(parent)
    local input = Instance.new("TextBox")
    input.Position = UDim2.fromOffset(10, 4)
    input.Size = UDim2.new(1, -20, 0, 34)
    input.BackgroundColor3 = Color3.fromRGB(28, 28, 28)
    input.BorderSizePixel = 0
    input.ClearTextOnFocus = false
    input.PlaceholderText = "Начните вводить ник..."
    input.Text = ""
    input.Font = Enum.Font.Code
    input.TextColor3 = Color3.fromRGB(235, 235, 235)
    input.PlaceholderColor3 = Color3.fromRGB(135, 135, 135)
    input.TextSize = 12
    input.Parent = parent
    corner(input)
    local list = Instance.new("ScrollingFrame")
    list.Position = UDim2.fromOffset(10, 48)
    list.Size = UDim2.new(1, -20, 0, 214)
    list.BackgroundColor3 = Color3.fromRGB(28, 28, 28)
    list.BorderSizePixel = 0
    list.ScrollBarThickness = 3
    list.CanvasSize = UDim2.fromOffset(0, 0)
    list.Parent = parent
    corner(list)
    local layout = Instance.new("UIListLayout")
    layout.Padding = UDim.new(0, 4)
    layout.Parent = list
    self.TeleportInput, self.TeleportList, self.TeleportLayout = input, list, layout
    self.ctx.Janitor:Add(input:GetPropertyChangedSignal("Text"):Connect(function() self:RenderPlayers() end))
    self.ctx.Janitor:Add(layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
        list.CanvasSize = UDim2.fromOffset(0, layout.AbsoluteContentSize.Y + 4)
    end))
    self:RenderPlayers()
end

function Movement:RenderPlayers()
    if not self.TeleportList then return end
    for _, child in ipairs(self.TeleportList:GetChildren()) do
        if child:IsA("TextButton") then child:Destroy() end
    end
    local query = string.lower(self.TeleportInput.Text:gsub("^@", ""))
    local players = {}
    for _, player in ipairs(self.ctx.Players:GetPlayers()) do
        if player ~= self.ctx.LocalPlayer then
            local name, display = string.lower(player.Name), string.lower(player.DisplayName)
            if query == "" or string.sub(name, 1, #query) == query or string.sub(display, 1, #query) == query then
                table.insert(players, player)
            end
        end
    end
    table.sort(players, function(a, b) return string.lower(a.Name) < string.lower(b.Name) end)
    for index, player in ipairs(players) do
        local row = self.ctx.Window:Button(self.TeleportList, UDim2.new(), UDim2.new(1, -4, 0, 32), player.DisplayName .. "  @" .. player.Name, function()
            self:TeleportTo(player)
        end)
        row.LayoutOrder = index
        row.TextXAlignment = Enum.TextXAlignment.Left
    end
end

function Movement:TeleportTo(player)
    local character, _, root = self:CharacterParts()
    local targetRoot = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
    if character and root and targetRoot then character:PivotTo(targetRoot.CFrame * CFrame.new(0, 0, 3)) end
end

function Movement:GetConfig()
    local savedNoclip = self.Noclip
    if self.ForcedNoclipPrevious ~= nil then savedNoclip = self.ForcedNoclipPrevious == true end
    return {
        speed = self.Speed, speedValue = self.SpeedValue,
        jump = self.Jump, jumpValue = self.JumpValue,
        noclip = savedNoclip, fly = self.Fly, flySpeed = self.FlySpeed,
        binds = {
            Speed = {key = self.Bindings.Speed, mode = self.BindModes.Speed},
            Jump = {key = self.Bindings.Jump, mode = self.BindModes.Jump},
            Noclip = {key = self.Bindings.Noclip, mode = self.BindModes.Noclip},
            Fly = {key = self.Bindings.Fly, mode = self.BindModes.Fly},
        },
    }
end

function Movement:ApplyConfig(data)
    if type(data) ~= "table" then return end
    self.Speed = data.speed == true; self.SpeedValue = math.clamp(tonumber(data.speedValue) or self.SpeedValue, 0, 200)
    self.Jump = data.jump == true; self.JumpValue = math.clamp(tonumber(data.jumpValue) or self.JumpValue, 25, 250)
    self.Noclip = data.noclip == true; self.Fly = data.fly == true
    self.FlySpeed = math.clamp(tonumber(data.flySpeed) or self.FlySpeed, 10, 250)
    local binds = type(data.binds) == "table" and data.binds or {}
    for _, feature in ipairs(BINDABLE) do
        local entry = type(binds[feature]) == "table" and binds[feature] or {}
        self.Bindings[feature] = type(entry.key) == "string" and entry.key or nil
        self.BindModes[feature] = entry.mode == "Hold" and "Hold" or "Toggle"
        self:DrawBinding(feature)
    end
    self.SpeedControl.Set(self.Speed); self.SpeedValueControl.Set(self.SpeedValue)
    self.JumpControl.Set(self.Jump); self.JumpValueControl.Set(self.JumpValue)
    self.NoclipControl.Set(self.Noclip); self.FlyControl.Set(self.Fly); self.FlyValueControl.Set(self.FlySpeed)
    self:ApplyHumanoid()
    self:RefreshLoops()
end

function Movement:Destroy()
    self.Fly = false
    self:StopFly()
    self:RestoreCollision()
    self.Speed, self.Jump = false, false
    self.Noclip = false
    self:DisconnectLoops()
    self:RestoreSpeed(); self:RestoreJump()
    self:DisconnectHumanoid()
end

return Movement
]====],
    ["features/Visuals"] = [====[
local Visuals = {}
Visuals.__index = Visuals

local WHITE = Color3.fromRGB(255, 255, 255)
local GREEN = Color3.fromRGB(65, 255, 105)

local function corner(parent, radius)
    local item = Instance.new("UICorner")
    item.CornerRadius = UDim.new(0, radius or 3)
    item.Parent = parent
end

local drawingSupported = false
local drawingCheck, drawingResult = pcall(function()
    return Drawing ~= nil and type(Drawing.new) == "function"
end)
drawingSupported = drawingCheck and drawingResult == true

local function newDrawing(kind)
    if not drawingSupported then return nil end
    local ok, result = pcall(function() return Drawing.new(kind) end)
    if not ok then drawingSupported = false end
    return ok and result or nil
end

local function removeDrawing(item)
    if item then pcall(function() item:Remove() end) end
end

function Visuals.new(ctx)
    local self = setmetatable({
        ctx = ctx, Bundles = {},
        ESP = false, Health = false,
        NameTags = false, ShowDisplay = true, ShowReal = false, ShowDistance = true,
        Chams = false, ChamsTransparency = 0.35,
        Lighting = false, LightR = 255, LightG = 220, LightB = 190, LightStrength = 15,
    }, Visuals)
    self:EnsureLightingEffect()

    local page = ctx.Window:AddPage("Visuals", "ESP, NameTags, Chams и освещение")
    local stack = ctx.Window:ModuleStack(page, 70)
    local esp = stack:Add("ESP", 88)
    self.ESPControl = ctx.Window:Toggle(esp.Settings, UDim2.fromOffset(10, 4), 180, "Box", false, function(v) self.ESP = v; self:RefreshRenderLoop(); ctx.Touch() end)
    self.HealthControl = ctx.Window:Toggle(esp.Settings, UDim2.fromOffset(200, 4), 180, "Health Bar", false, function(v) self.Health = v; self:RefreshRenderLoop(); ctx.Touch() end)

    local tags = stack:Add("NameTags", 138)
    self.TagsControl = ctx.Window:Toggle(tags.Settings, UDim2.fromOffset(10, 4), 155, "Enabled", false, function(v) self.NameTags = v; self:RefreshRenderLoop(); ctx.Touch() end)
    self.DisplayControl = ctx.Window:Toggle(tags.Settings, UDim2.fromOffset(175, 4), 155, "Display name", true, function(v) self.ShowDisplay = v; ctx.Touch() end)
    self.RealControl = ctx.Window:Toggle(tags.Settings, UDim2.fromOffset(340, 4), 155, "Real name", false, function(v) self.ShowReal = v; ctx.Touch() end)
    self.DistanceControl = ctx.Window:Toggle(tags.Settings, UDim2.fromOffset(10, 48), 155, "Meters", true, function(v) self.ShowDistance = v; ctx.Touch() end)

    local chams = stack:Add("Chams", 132)
    self.ChamsControl = ctx.Window:Toggle(chams.Settings, UDim2.fromOffset(10, 4), 190, "Enabled", false, function(v) self.Chams = v; self:RefreshRenderLoop(); ctx.Touch() end)
    self.TransparencyControl = ctx.Window:Slider(chams.Settings, 48, "Transparency", 35, 0, 100, 1, function(v) self.ChamsTransparency = v / 100; ctx.Touch() end)

    local lighting = stack:Add("Lighting", 172)
    self.LightingControl = ctx.Window:Toggle(lighting.Settings, UDim2.fromOffset(10, 4), 190, "Enabled", false, function(v)
        self.Lighting = v
        self:UpdateLighting()
        self:RefreshLightingLoop()
        ctx.Touch()
    end)
    self.ColorControl = ctx.Window:ColorPicker(lighting.Settings, UDim2.fromOffset(10, 48), 260, "Tint color", Color3.fromRGB(self.LightR, self.LightG, self.LightB), function(value)
        self.LightR = math.round(value.R * 255)
        self.LightG = math.round(value.G * 255)
        self.LightB = math.round(value.B * 255)
        self:UpdateLighting()
        ctx.Touch()
    end)
    self.StrengthControl = ctx.Window:Slider(lighting.Settings, 88, "Strength", 15, -100, 100, 1, function(v) self.LightStrength = v; self:UpdateLighting(); ctx.Touch() end)

    ctx.Janitor:Add(ctx.Players.PlayerRemoving:Connect(function(player) self:Remove(player) end))
    ctx.Janitor:Add(function()
        if self.RenderLoop then self.RenderLoop:Disconnect(); self.RenderLoop = nil end
        if self.LightingLoop then self.LightingLoop:Disconnect(); self.LightingLoop = nil end
    end)
    ctx.Janitor:Add(ctx.Workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function()
        if self.Lighting then self:UpdateLighting() end
    end))
    return self
end

function Visuals:RefreshRenderLoop()
    local active = self.ESP or self.Health or self.NameTags or self.Chams
    if not active then
        if self.RenderLoop then self.RenderLoop:Disconnect(); self.RenderLoop = nil end
        if next(self.Bundles) then self:ResetBundles() end
        return
    end
    if self.RenderLoop then return end
    self.RenderElapsed = 0
    self.RenderLoop = self.ctx.RunService.RenderStepped:Connect(function(delta)
        local screenVisuals = self.ESP or self.Health or self.NameTags
        local hasPlayerVisuals = screenVisuals or self.Chams
        if not hasPlayerVisuals then
            if next(self.Bundles) then self:ResetBundles() end
            return
        end
        self.RenderElapsed = (self.RenderElapsed or 0) + delta
        local interval = screenVisuals and (1 / 30) or 0.15
        if self.RenderElapsed < interval then return end
        self.RenderElapsed = 0
        local ok, message = pcall(function() self:Step() end)
        if not ok then
            drawingSupported = false
            self:ResetBundles()
            if not self.Warned then self.Warned = true; warn("[BezNigativa/Visuals] " .. tostring(message)) end
        end
    end)
end

function Visuals:CreateBundle(player, character, root, createScreenObjects)
    local bundle = {Character = character}
    local highlight = Instance.new("Highlight")
    highlight.Name = "BezNigativaVisual"
    highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
    highlight.Enabled = false
    highlight.Parent = character
    bundle.Highlight = highlight
    if not createScreenObjects then
        self.Bundles[player] = bundle
        return bundle
    end
    bundle.Box = newDrawing("Square")
    bundle.HealthBack = bundle.Box and newDrawing("Square") or nil
    bundle.HealthFill = bundle.Box and newDrawing("Square") or nil
    bundle.Tag = bundle.Box and newDrawing("Text") or nil
    local drawingReady = bundle.Box and bundle.HealthBack and bundle.HealthFill and bundle.Tag
    if drawingReady then
        drawingReady = pcall(function()
            bundle.Box.Filled, bundle.Box.Thickness = false, 1.5
            bundle.HealthBack.Filled, bundle.HealthBack.Color = true, Color3.fromRGB(20, 20, 20)
            bundle.HealthFill.Filled = true
            bundle.Tag.Center, bundle.Tag.Outline, bundle.Tag.Size = true, true, 14
        end)
    end
    if not drawingReady then
        drawingSupported = false
        removeDrawing(bundle.Box); removeDrawing(bundle.HealthBack); removeDrawing(bundle.HealthFill); removeDrawing(bundle.Tag)
        bundle.Box, bundle.HealthBack, bundle.HealthFill, bundle.Tag = nil, nil, nil, nil
        local gui = Instance.new("BillboardGui")
        gui.Name = "BezNigativaPlayerInfo"
        gui.Adornee = root
        gui.AlwaysOnTop = true
        gui.LightInfluence = 0
        gui.Size = UDim2.fromOffset(180, 48)
        gui.StudsOffsetWorldSpace = Vector3.new(0, 3.2, 0)
        gui.Enabled = false
        gui.Parent = self.ctx.Window.Gui.Parent
        bundle.Gui = gui
        local tag = Instance.new("TextLabel")
        tag.Size = UDim2.new(1, 0, 0, 20)
        tag.BackgroundTransparency = 1
        tag.Font = Enum.Font.Code
        tag.TextSize = 14
        tag.TextStrokeTransparency = 0.25
        tag.Parent = gui
        bundle.GuiTag = tag
        local healthBack = Instance.new("Frame")
        healthBack.Position = UDim2.new(0.5, -35, 0, 24)
        healthBack.Size = UDim2.fromOffset(70, 5)
        healthBack.BackgroundColor3 = Color3.fromRGB(20, 20, 20)
        healthBack.BorderSizePixel = 0
        healthBack.Parent = gui
        corner(healthBack, 2)
        local healthFill = Instance.new("Frame")
        healthFill.Size = UDim2.fromScale(1, 1)
        healthFill.BorderSizePixel = 0
        healthFill.Parent = healthBack
        corner(healthFill, 2)
        bundle.GuiHealthBack, bundle.GuiHealthFill = healthBack, healthFill
    end
    self.Bundles[player] = bundle
    return bundle
end

function Visuals:Remove(player)
    local bundle = self.Bundles[player]
    if not bundle then return end
    if bundle.Highlight then bundle.Highlight:Destroy() end
    if bundle.Gui then bundle.Gui:Destroy() end
    removeDrawing(bundle.Box); removeDrawing(bundle.HealthBack); removeDrawing(bundle.HealthFill); removeDrawing(bundle.Tag)
    self.Bundles[player] = nil
end

function Visuals:ResetBundles()
    local players = {}
    for player in pairs(self.Bundles) do table.insert(players, player) end
    for _, player in ipairs(players) do self:Remove(player) end
end

function Visuals:Bounds(character, camera)
    local root = character:FindFirstChild("HumanoidRootPart")
    if not root then return nil end
    local _, rootVisible = camera:WorldToViewportPoint(root.Position)
    if not rootVisible then return nil end
    local cf, size = character:GetBoundingBox()
    local half = size * 0.5
    local minX, minY, maxX, maxY = math.huge, math.huge, -math.huge, -math.huge
    local points = 0
    for x = -1, 1, 2 do
        for y = -1, 1, 2 do
            for z = -1, 1, 2 do
                local worldPoint = cf:PointToWorldSpace(Vector3.new(half.X * x, half.Y * y, half.Z * z))
                local screen = camera:WorldToViewportPoint(worldPoint)
                if screen.Z > 0 then
                    points += 1
                    minX, minY = math.min(minX, screen.X), math.min(minY, screen.Y)
                    maxX, maxY = math.max(maxX, screen.X), math.max(maxY, screen.Y)
                end
            end
        end
    end
    local width, height = maxX - minX, maxY - minY
    if points < 2 or width <= 1 or height <= 1 or width > 3000 or height > 3000 then return nil end
    return minX, minY, maxX, maxY
end

function Visuals:HideDrawing(bundle)
    for _, name in ipairs({"Box", "HealthBack", "HealthFill", "Tag"}) do
        if bundle[name] then bundle[name].Visible = false end
    end
end

function Visuals:TagText(player, distance)
    local parts = {}
    if self.ShowDisplay then table.insert(parts, player.DisplayName) end
    if self.ShowReal and (not self.ShowDisplay or player.DisplayName ~= player.Name) then table.insert(parts, "@" .. player.Name) end
    if self.ShowDistance then table.insert(parts, tostring(math.floor(distance + 0.5)) .. "m") end
    return table.concat(parts, "  ")
end

function Visuals:Step()
    local screenVisuals = self.ESP or self.Health or self.NameTags
    if not screenVisuals and not self.Chams then
        if next(self.Bundles) then self:ResetBundles() end
        return
    end
    local camera = self.ctx.Workspace.CurrentCamera
    if not camera then return end
    local localCharacter = self.ctx.LocalPlayer.Character
    local localRoot = localCharacter and localCharacter:FindFirstChild("HumanoidRootPart")
    for _, player in ipairs(self.ctx.Players:GetPlayers()) do
        if player ~= self.ctx.LocalPlayer then
            local character = player.Character
            local humanoid = character and character:FindFirstChildOfClass("Humanoid")
            local root = character and character:FindFirstChild("HumanoidRootPart")
            local bundle = self.Bundles[player]
            if bundle and (bundle.Character ~= character or not bundle.Highlight or not bundle.Highlight.Parent or (bundle.Gui and not bundle.Gui.Parent)) then
                self:Remove(player); bundle = nil
            end
            if bundle and screenVisuals and not bundle.Box and not bundle.Gui then self:Remove(player); bundle = nil end
            if not character or not humanoid or humanoid.Health <= 0 or not root then
                if bundle then
                    if bundle.Gui then bundle.Gui.Enabled = false end
                    if bundle.Highlight then bundle.Highlight.Enabled = false end
                    self:HideDrawing(bundle)
                end
            else
                bundle = bundle or self:CreateBundle(player, character, root, screenVisuals)
                local color = self.ctx.Friends:IsFriend(player) and GREEN or WHITE
                local healthRatio = screenVisuals and math.clamp(humanoid.Health / math.max(humanoid.MaxHealth, 1), 0, 1) or 0
                local distance = screenVisuals and localRoot and (localRoot.Position - root.Position).Magnitude or 0
                local tagText = screenVisuals and self:TagText(player, distance) or ""
                if screenVisuals and bundle.Box then
                    local minX, minY, maxX, maxY = self:Bounds(character, camera)
                    if minX then
                        bundle.Box.Visible = self.ESP
                        bundle.Box.Position = Vector2.new(minX, minY)
                        bundle.Box.Size = Vector2.new(maxX - minX, maxY - minY)
                        bundle.Box.Color = color
                        bundle.HealthBack.Visible, bundle.HealthFill.Visible = self.Health, self.Health
                        bundle.HealthBack.Position = Vector2.new(minX - 7, minY)
                        bundle.HealthBack.Size = Vector2.new(4, maxY - minY)
                        local height = (maxY - minY) * healthRatio
                        bundle.HealthFill.Position = Vector2.new(minX - 7, maxY - height)
                        bundle.HealthFill.Size = Vector2.new(4, math.max(1, height))
                        bundle.HealthFill.Color = Color3.fromRGB(255 * (1 - healthRatio), 255 * healthRatio, 40)
                        bundle.Tag.Visible = self.NameTags and tagText ~= ""
                        bundle.Tag.Position = Vector2.new((minX + maxX) / 2, minY - 20)
                        bundle.Tag.Text, bundle.Tag.Color = tagText, color
                    else
                        self:HideDrawing(bundle)
                    end
                elseif screenVisuals and bundle.Gui then
                    bundle.Gui.Adornee = root
                    bundle.Gui.Enabled = self.Health or (self.NameTags and tagText ~= "")
                    bundle.GuiTag.Visible = self.NameTags and tagText ~= ""
                    bundle.GuiTag.Text, bundle.GuiTag.TextColor3 = tagText, color
                    bundle.GuiHealthBack.Visible = self.Health
                    bundle.GuiHealthFill.Size = UDim2.fromScale(healthRatio, 1)
                    bundle.GuiHealthFill.BackgroundColor3 = Color3.fromRGB(255 * (1 - healthRatio), 255 * healthRatio, 40)
                else
                    if bundle.Gui then bundle.Gui.Enabled = false end
                    self:HideDrawing(bundle)
                end
                bundle.Highlight.Enabled = self.Chams or (self.ESP and not bundle.Box)
                bundle.Highlight.FillColor = color
                bundle.Highlight.FillTransparency = self.Chams and self.ChamsTransparency or 1
                bundle.Highlight.OutlineColor = color
                bundle.Highlight.OutlineTransparency = (self.ESP and not bundle.Box) and 0 or (self.Chams and 0.35 or 1)
            end
        end
    end
end

function Visuals:EnsureLightingEffect()
    local parent = self.ctx.Workspace.CurrentCamera or self.ctx.Lighting
    if self.Effect and self.Effect.Parent then
        if self.Effect.Parent ~= parent then self.Effect.Parent = parent end
        return self.Effect
    end

    local effect = Instance.new("ColorCorrectionEffect")
    effect.Name = "BezNigativaLighting"
    effect.Enabled = false
    effect.Brightness = 0
    effect.Contrast = 0
    effect.Saturation = 0
    effect.TintColor = Color3.new(1, 1, 1)
    effect.Parent = parent
    self.ctx.Janitor:Add(effect)
    self.Effect = effect
    return effect
end

function Visuals:UpdateLighting()
    local effect = self:EnsureLightingEffect()
    effect.Enabled = self.Lighting
    if not self.Lighting then return end
    effect.TintColor = Color3.fromRGB(self.LightR, self.LightG, self.LightB)
    effect.Brightness = math.clamp(self.LightStrength / 100, -1, 1)
end

function Visuals:RefreshLightingLoop()
    if self.Lighting and not self.LightingLoop then
        self.LightingElapsed = 0
        self.LightingLoop = self.ctx.RunService.Heartbeat:Connect(function(delta)
            self.LightingElapsed += delta
            if self.LightingElapsed < 0.2 then return end
            self.LightingElapsed = 0
            local ok, message = pcall(function() self:UpdateLighting() end)
            if not ok and not self.LightingWarned then
                self.LightingWarned = true
                warn("[BezNigativa/Lighting] " .. tostring(message))
            end
        end)
    elseif not self.Lighting and self.LightingLoop then
        self.LightingLoop:Disconnect()
        self.LightingLoop = nil
    end
end

function Visuals:GetConfig()
    return {
        esp = self.ESP, health = self.Health, nameTags = self.NameTags,
        showDisplay = self.ShowDisplay, showReal = self.ShowReal, showDistance = self.ShowDistance,
        chams = self.Chams, chamsTransparency = self.ChamsTransparency,
        lighting = self.Lighting, lightR = self.LightR, lightG = self.LightG, lightB = self.LightB, lightStrength = self.LightStrength,
    }
end

function Visuals:ApplyConfig(data)
    if type(data) ~= "table" then return end
    self.ESP, self.Health, self.NameTags = data.esp == true, data.health == true, data.nameTags == true
    self.ShowDisplay, self.ShowReal, self.ShowDistance = data.showDisplay ~= false, data.showReal == true, data.showDistance ~= false
    self.Chams = data.chams == true
    self.ChamsTransparency = math.clamp(tonumber(data.chamsTransparency) or self.ChamsTransparency, 0, 1)
    self.Lighting = data.lighting == true
    self.LightR = math.clamp(tonumber(data.lightR) or self.LightR, 0, 255)
    self.LightG = math.clamp(tonumber(data.lightG) or self.LightG, 0, 255)
    self.LightB = math.clamp(tonumber(data.lightB) or self.LightB, 0, 255)
    self.LightStrength = math.clamp(tonumber(data.lightStrength) or self.LightStrength, -100, 100)
    self.ESPControl.Set(self.ESP); self.HealthControl.Set(self.Health); self.TagsControl.Set(self.NameTags)
    self.DisplayControl.Set(self.ShowDisplay); self.RealControl.Set(self.ShowReal); self.DistanceControl.Set(self.ShowDistance)
    self.ChamsControl.Set(self.Chams); self.TransparencyControl.Set(self.ChamsTransparency * 100)
    self.LightingControl.Set(self.Lighting)
    self.ColorControl.Set(Color3.fromRGB(self.LightR, self.LightG, self.LightB))
    self.StrengthControl.Set(self.LightStrength)
    self:UpdateLighting()
    self:RefreshLightingLoop()
    self:RefreshRenderLoop()
end

function Visuals:Destroy()
    if self.RenderLoop then self.RenderLoop:Disconnect(); self.RenderLoop = nil end
    if self.LightingLoop then self.LightingLoop:Disconnect(); self.LightingLoop = nil end
    self.Lighting = false
    if self.Effect and self.Effect.Parent then self.Effect.Enabled = false end
    self:ResetBundles()
end

return Visuals
